static size_t est_strcspn(const char * str1,const char * str2){

    rsize_t count;
    errno_t safec_rc;

    if ((str1 != NULL) && (str1[0] == '\0')) {
        return 0;
    }

    safec_rc = strcspn_s(str1, strnlen_s(str1, RSIZE_MAX_STR),
            str2, RSIZE_MAX_STR, &count);
    if (safec_rc != EOK) {
        EST_LOG_INFO("strcspn_s error 0x%xO\n", safec_rc);
        return 0;
    }

    return count;

}
